const req = $('Webhook tìm sách').first().json;
let cfg = $input.first().json.cfg || {};
if (typeof cfg === 'string') cfg = JSON.parse(cfg);

const posInt = (v, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
};
const llm_models = String(cfg.llm_models || 'gemini-3.5-flash-lite,gemma-4-31b-it,gemini-3.8-flash')
  .split(/[\s,]+/).map((m) => m.trim()).filter((m) => /^[\w.-]{1,80}$/.test(m)).slice(0, 3);
const baseCfg = {
  llm_models: llm_models.length ? llm_models : ['gemini-3.5-flash-lite'],
  embed_model: String(cfg.embed_model || 'gemini-embedding-2').trim(),
  embed_dims: posInt(cfg.embed_dims, 768),
  top_k: Math.min(posInt(cfg.top_k, 10), 50),
  chat_k: Math.min(posInt(cfg.chat_k, 5), 10),
  cache_ttl_hours: posInt(cfg.cache_ttl_hours, 168),
  per_min: posInt(cfg.rate_limit_per_min, 10),
  per_day: posInt(cfg.rate_limit_per_day, 200),
  image_search_enabled: String(cfg.image_search_enabled || '').trim().toLowerCase() === 'true',
};

const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
const expected = String(cfg.biascan_token || '').trim();
const given = String(headers['x-biascan-token'] || '').trim();
const auth_ok = expected !== '' && given === expected;
const auth_message = expected === ''
  ? 'Máy chủ chưa cấu hình biascan_token trong bảng app_config.'
  : 'Thiếu hoặc sai header x-biascan-token.';

// n8n.thuanbt.id.vn chạy sau Fly proxy: chỉ fly-client-ip do proxy đặt; cf-connecting-ip / x-forwarded-for client tự gửi được.
const forwarded = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const ip = String(headers['fly-client-ip'] || '').trim()
  || String(headers['cf-connecting-ip'] || '').trim() || forwarded || 'unknown';
const session_id = typeof body.session_id === 'string' ? body.session_id.trim() : '';

const enc = (v) => {
  const s = JSON.stringify(v === undefined ? null : v);
  return typeof Buffer !== 'undefined'
    ? Buffer.from(s, 'utf8').toString('base64')
    : btoa(unescape(encodeURIComponent(s)));
};

const sha256 = (ascii) => {
  try {
    return require('crypto').createHash('sha256').update(ascii, 'utf8').digest('hex');
  } catch (e) { /* Code node chặn require('crypto') nếu thiếu NODE_FUNCTION_ALLOW_BUILTIN */ }
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const len = ascii.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const bitsHi = Math.floor(len / 0x20000000);
  const bitsLo = (len * 8) >>> 0;
  const byteAt = (i) => {
    if (i < len) return ascii.charCodeAt(i) & 0xff;
    if (i === len) return 0x80;
    const k = i - (total - 8);
    if (k < 0) return 0;
    return k < 4 ? (bitsHi >>> (24 - 8 * k)) & 0xff : (bitsLo >>> (24 - 8 * (k - 4))) & 0xff;
  };
  const W = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let t = 0; t < 16; t++) {
      const i = off + t * 4;
      W[t] = ((byteAt(i) << 24) | (byteAt(i + 1) << 16) | (byteAt(i + 2) << 8) | byteAt(i + 3)) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const mj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + mj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
};

const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
const IMAGE_MIMES = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'];

let input_error = '';
const query = typeof body.query === 'string' ? body.query.replace(/\s+/g, ' ').trim() : '';
let image_mime = '';
let image_b64 = '';

if (body.query !== undefined && body.query !== null && typeof body.query !== 'string') {
  input_error = 'Trường query phải là chuỗi.';
} else if (query.length > 1000) {
  input_error = 'Mô tả quá dài (tối đa 1000 ký tự).';
}

if (!input_error && typeof body.image === 'string' && body.image.trim() !== '') {
  const raw = body.image.trim();
  const m = raw.match(/^data:([a-z0-9.+\/-]+);base64,(.*)$/is);
  image_mime = m ? m[1].toLowerCase() : 'image/jpeg';
  image_b64 = (m ? m[2] : raw).replace(/\s+/g, '');
  if (image_mime === 'image/jpg') image_mime = 'image/jpeg';
  const padding = image_b64.endsWith('==') ? 2 : image_b64.endsWith('=') ? 1 : 0;
  const bytes = Math.floor((image_b64.length * 3) / 4) - padding;
  if (!IMAGE_MIMES.includes(image_mime)) {
    input_error = 'Định dạng ảnh không hỗ trợ (chỉ nhận JPEG, PNG, WEBP, HEIC).';
  } else if (!/^[A-Za-z0-9+/]+={0,2}$/.test(image_b64)) {
    input_error = 'Ảnh không phải base64 hợp lệ.';
  } else if (bytes > MAX_IMAGE_BYTES) {
    input_error = 'Ảnh lớn hơn 4 MB, hãy nén lại trước khi gửi.';
  }
} else if (!input_error && body.image !== undefined && body.image !== null && typeof body.image !== 'string') {
  input_error = 'Trường image phải là chuỗi data URL base64.';
}

if (!input_error && !session_id) input_error = 'Thiếu session_id.';
else if (!input_error && session_id.length > 200) input_error = 'session_id quá dài.';
if (!input_error && !query && !image_b64) input_error = 'Cần ít nhất một trong hai: query hoặc image.';

const has_image = !input_error && image_b64 !== '';
const img_key = auth_ok && has_image ? `img:${sha256(image_b64)}` : '';

return [{
  json: {
    t_start: Date.now(),
    auth_ok,
    auth_message,
    ip,
    input_error,
    query,
    session_id,
    has_image,
    image_mime: has_image ? image_mime : '',
    image_b64: has_image ? image_b64 : '',
    img_key,
    img_key_b64: enc(img_key),
    cfg: baseCfg,
  },
}];

const ctx = $('Kiểm tra token và đầu vào').first().json;
let payload = $input.first().json.payload;
if (typeof payload === 'string') payload = JSON.parse(payload);
const hit = Boolean(payload && typeof payload === 'object' && (payload.ocr_text || payload.ocr_title));
return [{
  json: {
    ...ctx,
    ocr_cached: hit,
    ocr_text: hit ? payload.ocr_text || null : null,
    ocr_title: hit ? String(payload.ocr_title || '') : '',
    ocr_ms: 0,
  },
}];

const thinkingLevel = (m) => {
  if (/^gemini-(3\.5-flash-lite|3\.6-flash|3-flash|3\.1-flash-lite)/.test(m)) return 'minimal';
  if (/^gemini-([3-9]|\d\d)/.test(m)) return 'low';
  return '';
};
const buildLlm = (models, prompt, schema, example, opts = {}) => {
  const texts = [];
  const gens = [];
  for (const m of models) {
    const gemma = /^gemma/i.test(m);
    const gen = { temperature: opts.temperature ?? 0, maxOutputTokens: opts.maxOutputTokens ?? 1024 };
    if (!gemma) {
      gen.responseMimeType = 'application/json';
      gen.responseSchema = schema;
    }
    const lvl = thinkingLevel(m);
    if (lvl) gen.thinkingConfig = { thinkingLevel: lvl };
    gens.push(gen);
    texts.push(gemma
      ? `${prompt}\n\nChỉ trả về đúng một đối tượng JSON theo mẫu sau, không thêm chữ hay markdown nào khác:\n${example}`
      : prompt);
  }
  return { models, media: opts.media || [], texts, gens };
};

const ctx = $input.first().json;
const prompt = [
  'Ảnh là bìa trước của một cuốn sách, có thể bị nghiêng, mờ, lóa hoặc che một phần.',
  'Đọc chữ trên bìa và trả về JSON với các trường:',
  '- title: tên sách đúng nguyên văn trên bìa (giữ dấu tiếng Việt), chuỗi rỗng nếu không đọc được;',
  '- author: tác giả / dịch giả nếu thấy, chuỗi rỗng nếu không;',
  '- publisher: nhà xuất bản hoặc đơn vị phát hành (logo, chữ nhỏ) nếu thấy, chuỗi rỗng nếu không;',
  '- other_text: chữ đáng chú ý khác như phụ đề, tên bộ sách, tối đa 200 ký tự.',
  'Chỉ ghi chữ thực sự có trên ảnh, không đoán, không bịa.',
].join('\n');
const str = { type: 'STRING' };
const schema = {
  type: 'OBJECT',
  properties: { title: str, author: str, publisher: str, other_text: str },
  required: ['title', 'author', 'publisher', 'other_text'],
};
const example = '{"title": "", "author": "", "publisher": "", "other_text": ""}';

return [{
  json: {
    ...ctx,
    t_ocr: Date.now(),
    llm: buildLlm(ctx.cfg.llm_models, prompt, schema, example, {
      media: [{ inlineData: { mimeType: ctx.image_mime, data: ctx.image_b64 } }],
      maxOutputTokens: 512,
    }),
  },
}];

const { llm, ...ctx } = $('Chuẩn bị OCR').first().json;

const resp = $input.first().json || {};
const parts = resp.candidates?.[0]?.content?.parts || [];
const llm_text = parts.filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
const softJson = (t) => {
  try { return JSON.parse(t); } catch (e) { /* bóc khối {...} */ }
  const s = String(t || '').replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
  }
  return null;
};
const parsed = softJson(llm_text) || {};
const llm_model = String(resp.modelVersion || '');

const enc = (v) => {
  const s = JSON.stringify(v === undefined ? null : v);
  return typeof Buffer !== 'undefined'
    ? Buffer.from(s, 'utf8').toString('base64')
    : btoa(unescape(encodeURIComponent(s)));
};

const clean = (v) => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : '');
const title = clean(parsed.title);
const lines = [];
if (title) lines.push(`Tên sách: ${title}`);
if (clean(parsed.author)) lines.push(`Tác giả: ${clean(parsed.author)}`);
if (clean(parsed.publisher)) lines.push(`Nhà xuất bản: ${clean(parsed.publisher)}`);
if (clean(parsed.other_text)) lines.push(clean(parsed.other_text).slice(0, 200));
const ocr_text = lines.length ? lines.join('\n') : null;

return [{
  json: {
    ...ctx,
    ocr_text,
    ocr_title: title,
    ocr_model: llm_model,
    ocr_ms: Date.now() - ctx.t_ocr,
    // Không cache kết quả rỗng: lần sau có thể model khác đọc được.
    ocr_cache_key_b64: enc(ocr_text ? ctx.img_key : ''),
    ocr_cache_b64: enc({ ocr_text, ocr_title: title }),
  },
}];

const src = $('Đọc kết quả OCR').isExecuted ? 'Đọc kết quả OCR'
  : $('Đọc cache ảnh').isExecuted ? 'Đọc cache ảnh' : 'Bỏ qua OCR';
const { ocr_cache_key_b64, ocr_cache_b64, img_key_b64, ...ctx } = $(src).first().json;

const norm = (s) => String(s || '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/\p{Mn}/gu, '').normalize('NFC')
  .toLowerCase().replace(/[^\p{L}\p{N}\s]+/gu, ' ').replace(/\s+/g, ' ').trim();

const enc = (v) => {
  const s = JSON.stringify(v === undefined ? null : v);
  return typeof Buffer !== 'undefined'
    ? Buffer.from(s, 'utf8').toString('base64')
    : btoa(unescape(encodeURIComponent(s)));
};

const query_text = [ctx.ocr_text, ctx.query].filter(Boolean).join('\n');
const query_norm = norm(ctx.ocr_title || ctx.query);
const do_image_embed = Boolean(ctx.has_image && ctx.cfg.image_search_enabled);
const isE2 = ctx.cfg.embed_model.startsWith('gemini-embedding-2');
const request = {
  content: { parts: [{ text: isE2 ? `task: search result | query: ${query_text}` : query_text }] },
  outputDimensionality: ctx.cfg.embed_dims,
};
// gemini-embedding-2 từ chối taskType; model cũ (gemini-embedding-001...) thì dùng RETRIEVAL_QUERY.
if (!isE2) request.taskType = 'RETRIEVAL_QUERY';

// Khoá cache = toàn bộ chữ đem embed (OCR + mô tả) đã chuẩn hoá; quá dài thì băm. Tìm hybrid (có vector ảnh) không cache.
const full = norm(query_text);
let q_key = '';
if (!do_image_embed && full) q_key = full.length <= 300 ? `q:${full}` : `q:${full.slice(0, 200)}#${full.length}:${full.split('').reduce((h, c) => (Math.imul(h, 31) + c.charCodeAt(0)) >>> 0, 7)}`;

return [{
  json: {
    ...ctx,
    image_b64: do_image_embed ? ctx.image_b64 : '',
    query_text,
    query_norm,
    query_norm_b64: enc(query_norm),
    q_key_b64: enc(q_key),
    has_text: query_text.trim() !== '',
    do_image_embed,
    embed_request: request,
  },
}];

const ctx = $('Chuẩn bị embed').first().json;
let payload = $input.first().json.payload;
if (typeof payload === 'string') payload = JSON.parse(payload);
const hit = Boolean(payload && Array.isArray(payload.results));
const out = { ...ctx, q_hit: hit, t_embed: Date.now() };
if (hit) {
  out.response = {
    ocr_text: ctx.ocr_text,
    results: payload.results,
    cached: true,
    timings_ms: { ocr: ctx.ocr_ms, embed: 0, search: 0, rerank: 0, total: Date.now() - ctx.t_start },
  };
}
return [{ json: out }];

const { embed_request, response, ...ctx } = $('Đọc cache tìm').first().json;
const values = $input.first().json.embedding?.values;
if (!Array.isArray(values) || values.length !== ctx.cfg.embed_dims) {
  throw new Error(`Embedding câu hỏi sai số chiều: ${Array.isArray(values) ? values.length : 'không có'} (cần ${ctx.cfg.embed_dims})`);
}
const now = Date.now();
return [{ json: { ...ctx, text_vec: `[${values.join(',')}]`, embed_ms: now - ctx.t_embed, t_search: now } }];

const ctx = $('Nhận vector câu hỏi').first().json;
const values = $input.first().json.embedding?.values;
if (!Array.isArray(values) || values.length !== ctx.cfg.embed_dims) {
  throw new Error(`Embedding ảnh sai số chiều: ${Array.isArray(values) ? values.length : 'không có'} (cần ${ctx.cfg.embed_dims})`);
}
const now = Date.now();
return [{
  json: { ...ctx, image_b64: '', image_vec: `[${values.join(',')}]`, embed_ms: now - ctx.t_embed, t_search: now },
}];

const viaImage = $('Nhận vector ảnh').isExecuted;
const ctx = viaImage ? $('Nhận vector ảnh').first().json : $('Nhận vector câu hỏi').first().json;

const enc = (v) => {
  const s = JSON.stringify(v === undefined ? null : v);
  return typeof Buffer !== 'undefined'
    ? Buffer.from(s, 'utf8').toString('base64')
    : btoa(unescape(encodeURIComponent(s)));
};

const now = Date.now();
let rows = $input.first().json.rows;
if (typeof rows === 'string') rows = JSON.parse(rows);
if (!Array.isArray(rows)) rows = [];

const s = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));
const results = rows.map((r) => ({
  image_id: s(r.image_id),
  title: s(r.title),
  author: s(r.author),
  publisher: s(r.publisher),
  supplier: s(r.supplier),
  image_url: s(r.image_url),
  product_url: s(r.product_url),
  score: Math.round((Number(r.score) || 0) * 10000) / 10000,
  reason: null,
})).filter((h) => h.image_id).slice(0, ctx.cfg.top_k);

return [{
  json: {
    ocr_text: ctx.ocr_text,
    results,
    cached: false,
    timings_ms: { ocr: ctx.ocr_ms, embed: ctx.embed_ms, search: now - ctx.t_search, rerank: 0, total: now - ctx.t_start },
    cache_key_b64: ctx.q_key_b64,
    cache_b64: enc({ results }),
  },
}];

// 429 ở bất kỳ lần gọi Gemini nào của request (embed hoặc model trong chuỗi) ⇒ hết quota free.
const isQuota = (j) => /RESOURCE_EXHAUSTED|"(statusCode|status|httpCode|code)":\s*"?429\b|status code 429|\b429 Too Many/i
  .test(JSON.stringify(j || {}));
let quota = $input.all().some((it) => isQuota(it.json));
for (const n of ["OCR: Gemini 1", "OCR: Gemini 2", "OCR: Gemini 3", "Gemini embed câu hỏi"]) {
  if (quota) break;
  try {
    if ($(n).isExecuted) quota = $(n).all(1).some((it) => isQuota(it.json));
  } catch (e) { /* node chưa chạy hoặc không có nhánh lỗi */ }
}
return [{ json: { quota } }];

const req = $('Webhook chat').first().json;
let cfg = $input.first().json.cfg || {};
if (typeof cfg === 'string') cfg = JSON.parse(cfg);

const posInt = (v, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
};
const llm_models = String(cfg.llm_models || 'gemini-3.5-flash-lite,gemma-4-31b-it,gemini-3.8-flash')
  .split(/[\s,]+/).map((m) => m.trim()).filter((m) => /^[\w.-]{1,80}$/.test(m)).slice(0, 3);
const baseCfg = {
  llm_models: llm_models.length ? llm_models : ['gemini-3.5-flash-lite'],
  embed_model: String(cfg.embed_model || 'gemini-embedding-2').trim(),
  embed_dims: posInt(cfg.embed_dims, 768),
  top_k: Math.min(posInt(cfg.top_k, 10), 50),
  chat_k: Math.min(posInt(cfg.chat_k, 5), 10),
  cache_ttl_hours: posInt(cfg.cache_ttl_hours, 168),
  per_min: posInt(cfg.rate_limit_per_min, 10),
  per_day: posInt(cfg.rate_limit_per_day, 200),
  image_search_enabled: String(cfg.image_search_enabled || '').trim().toLowerCase() === 'true',
};

const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
const expected = String(cfg.biascan_token || '').trim();
const given = String(headers['x-biascan-token'] || '').trim();
const auth_ok = expected !== '' && given === expected;
const auth_message = expected === ''
  ? 'Máy chủ chưa cấu hình biascan_token trong bảng app_config.'
  : 'Thiếu hoặc sai header x-biascan-token.';

// n8n.thuanbt.id.vn chạy sau Fly proxy: chỉ fly-client-ip do proxy đặt; cf-connecting-ip / x-forwarded-for client tự gửi được.
const forwarded = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const ip = String(headers['fly-client-ip'] || '').trim()
  || String(headers['cf-connecting-ip'] || '').trim() || forwarded || 'unknown';
const session_id = typeof body.session_id === 'string' ? body.session_id.trim() : '';

const message = typeof body.message === 'string' ? body.message.trim() : '';
let context_ids = [];
let input_error = '';

