}
const viewing = new Set(ctx.context_ids);
const list = books.map((b) => `[${b.image_id}]${viewing.has(b.image_id) ? ' (khách đang xem)' : ''} ${one(b.title, 160)}`
  + ` | ${one(b.author, 80) || '-'} | ${one(b.publisher, 80) || '-'}: ${one(b.description, 200)}`).join('\n');
const history = arr(row.history)
  .map((t) => `${t.role === 'assistant' ? 'Tư vấn' : 'Khách'}: ${one(t.content, 300)}`).join('\n');

const prompt = [
  'Bạn là tư vấn viên nhà sách BiaScan (dữ liệu Fahasa). Trả lời tiếng Việt, thân thiện, tối đa ~120 từ, markdown, in đậm tên sách.',
  'Chỉ giới thiệu sách có trong DANH SÁCH; dẫn đúng tên và tác giả. Không bịa sách, nội dung, giá, khuyến mãi, tồn kho.',
  'Không cuốn nào hợp thì nói thật và mời khách mô tả rõ hơn. Câu hỏi ngoài chủ đề sách: từ chối lịch sự.',
  '',
  'DANH SÁCH:',
  list || '(trống)',
  '',
  history ? `LỊCH SỬ:\n${history}\n` : '',
  `KHÁCH: ${ctx.message}`,
  '',
  'Trả JSON: reply (markdown), suggestions (tối đa 3 câu khách có thể hỏi tiếp, mỗi câu dưới 12 từ, viết như lời khách),',
  'picks (image_id các sách nhắc trong reply, chỉ lấy từ DANH SÁCH, tối đa 4).',
].filter((l) => l !== null).join('\n');
const schema = {
  type: 'OBJECT',
  properties: {
    reply: { type: 'STRING' },
    suggestions: { type: 'ARRAY', items: { type: 'STRING' } },
    picks: { type: 'ARRAY', items: { type: 'STRING' } },
  },
  required: ['reply', 'suggestions', 'picks'],
};
const example = '{"reply": "...", "suggestions": ["..."], "picks": ["fahasa_1"]}';

return [{
  json: {
    session_b64: ctx.session_b64,
    message: ctx.message,
    t_start: ctx.t_start,
    books: books.map(({ description, ...card }) => card),
    llm: buildLlm(ctx.cfg.llm_models, prompt, schema, example, { temperature: 0.4, maxOutputTokens: 1024 }),
  },
}];

const ctx = $('Chat: chuẩn bị prompt').first().json;

const resp = $input.first().json || {};
const parts = resp.candidates?.[0]?.content?.parts || [];
const llm_text = parts.filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
const softJson = (t) => {
  try { return JSON.parse(t); } catch (e) { /* bóc khối {...} */ }
  const s = String(t || '').replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
  }
  return null;
};
const parsed = softJson(llm_text) || {};
const llm_model = String(resp.modelVersion || '');

const enc = (v) => {
  const s = JSON.stringify(v === undefined ? null : v);
  return typeof Buffer !== 'undefined'
    ? Buffer.from(s, 'utf8').toString('base64')
    : btoa(unescape(encodeURIComponent(s)));
};

let reply = typeof parsed.reply === 'string' ? parsed.reply.trim() : '';
if (!reply && llm_text && !llm_text.startsWith('{') && !llm_text.startsWith('```')) reply = llm_text;
if (!reply) reply = 'Xin lỗi, mình chưa trả lời được câu này. Bạn thử hỏi lại theo cách khác nhé.';
