  .filter((id) => typeof id === 'string')
  .map((id) => id.trim().replace(/^\[|\]$/g, '')))].filter((id) => byId.has(id)).slice(0, 4);

return [{
  json: {
    reply,
    suggestions,
    products: ids.map((id) => byId.get(id)),
    session_b64: ctx.session_b64,
    message_b64: enc(ctx.message),
    reply_b64: enc(reply),
  },
}];

// 429 ở bất kỳ lần gọi Gemini nào của request (embed hoặc model trong chuỗi) ⇒ hết quota free.
const isQuota = (j) => /RESOURCE_EXHAUSTED|"(statusCode|status|httpCode|code)":\s*"?429\b|status code 429|\b429 Too Many/i
