else if (!query) input_error = 'Thiếu query.';
else if (query.length > 1000) input_error = 'query quá dài (tối đa 1000 ký tự).';
else if (!Array.isArray(body.image_ids) || body.image_ids.some((id) => typeof id !== 'string' || !/^[\w.-]{1,64}$/.test(id.trim()))) {
