} else {
  image_ids = [...new Set(body.image_ids.map((id) => id.trim()))];
  if (image_ids.length < 1 || image_ids.length > 3) input_error = 'image_ids phải là mảng 1–3 mã sách.';
}
const qn = norm(query);
const why_key = input_error ? '' : `why:${qn.length <= 300 ? qn : qn.slice(0, 300)}|${[...image_ids].sort().join('|')}`;

return [{
  json: {
    auth_ok, auth_message, ip, input_error, session_id, query, image_ids,
